<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link rel="stylesheet" href="styles.css">
    <title>CSS Example</title>
</head>
<body>
    <div class="container">
        <h1>Hello, World!</h1>
        <p>This is a paragraph with modern CSS features.</p>
        <button>Click Me</button>
