### `src/charts/barChart.js`
```javascript
import * as d3 from 'd3';

function generateBarChart(data) {
  const width = 500;
  const height = 300;
  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height);

  const x = d3.scaleBand()
    .domain(data.map(d => d.name))
    .range([0, width])
    .padding(0.1);

  const y = d3.scaleLinear()
    .domain([0, d3.max(data, d => d.value)])
    .nice()
    .range([height, 0]);

  svg.append("g")
    .selectAll("rect")
    .data(data)
    .enter().append("rect")
      .attr("x", d => x(d.name))
      .attr("y", d => y(d.value))
      .attr("width", x.bandwidth())
      .attr("height", d => height - y(d.value))
      .attr("fill", "steelblue");

  svg.append("g")
    .call(d3.axisLeft(y));

  svg.append("g")
    .attr("transform", `translate(0,${height})`)
    .call(d3.axisBottom(x));

  return svg.node();
}

module.exports = generateBarChart;
```

### `src/charts/lineChart.js`
```javascript
import * as d3 from 'd3';

function generateLineChart(data) {
  const width = 500;
  const height = 300;
  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height);

  const x = d3.scaleBand()
    .domain(data.map(d => d.name))
    .range([0, width]);

  const y = d3.scaleLinear()
    .domain([0, d3.max(data, d => d.value)])
    .nice()
    .range([height, 0]);

  const line = d3.line()
    .x(d => x(d.name))
    .y(d => y(d.value));

  svg.append("path")
    .datum(data)
    .attr("fill", "none")
    .attr("stroke", "steelblue")
    .attr("stroke-width", 1.5)
    .attr("d", line);

  svg.append("g")
    .call(d3.axisLeft(y));

  svg.append("g")
    .attr("transform", `translate(0,${height})`)
    .call(d3.axisBottom(x));

  return svg.node();
}

module.exports = generateLineChart;
```

### `src/charts/pieChart.js`
```javascript
import * as d3 from 'd3';

function generatePieChart(data) {
  const width = 500;
  const height = 300;
  const radius = Math.min(width, height) / 2;
  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height)
    .append("g")
    .attr("transform", `translate(${width / 2},${height / 2})`);

  const pie = d3.pie()
    .value(d => d.value);

  const arc = d3.arc()
    .outerRadius(radius - 10)
    .innerRadius(0);

  const arcs = svg.selectAll(".arc")
    .data(pie(data))
    .enter().append("g")
    .attr("class", "arc");

  arcs.append("path")
    .attr("d", arc)
    .attr("fill", d => d3.schemeCategory10[d.index]);

  return svg.node();
}

module.exports = generatePieChart;
```

