```javascript
import React, { useState } from 'react';

const CountFullStopLines = () => {
  const [text, setText] = useState('');
  const [count, setCount] = useState(0);

  const handleChange = (e) => {
    const newText = e.target.value;
    setText(newText);

    // Count lines ending with a full stop
    const lines = newText.split('\n');
    const fullStopLines = lines.filter(line => line.trim().endsWith('.')).length;
    setCount(fullStopLines);
  };

  return (
    <div>
      <textarea value={text} onChange={handleChange} rows="10" cols="50" />
      <label>Lines ending with a full stop: {count}</label>
    </div>
  );
};

export default CountFullStopLines;
```

This component keeps track of the text in the textarea and the number of lines ending with a full stop. The `handleChange` function updates both the text and the count state whenever the textarea's value changes.

