If you want to dynamically generate bundles for each `.js` file in a specific directory (`src/js/lib`), here is an example of how to configure `webpack.config.js`:

```javascript
const path = require('path');
const fs = require('fs');

// Function to get all JavaScript files in a directory
function getJavaScriptFiles(dir) {
  return fs.readdirSync(dir)
    .filter(file => file.endsWith('.js'))
    .reduce((entries, file) => {
      const entryName = path.basename(file, '.js');
      entries[entryName] = path.resolve(dir, file);
      return entries;
    }, {});
}

module.exports = {
  mode: 'development', // or 'production'
  entry: getJavaScriptFiles('./src/js/lib'), // Dynamically get all JS files in src/js/lib
  output: {
    filename: '[name].bundle.js', // Dynamically name output bundles based on entry keys
    path: path.resolve(__dirname, 'dist')
  },
  module: {
    rules: [
      {
        test: /\.js$/,
        exclude: /node_modules/,
        use: {
          loader: 'babel-loader'
        }
      }
    ]
  },
  watch: true // Optional: Enable watch mode if desired
};
```

With this setup, webpack will create a separate bundle for each `.js` file in the `src/js/lib` directory, and the script in `package.json` will ensure that webpack runs in watch mode to monitor changes and rebuild bundles as needed.

