   package com.example.graphql;

   import graphql.schema.GraphQLSchema;
   import org.springframework.context.annotation.Bean;
   import org.springframework.context.annotation.Configuration;
   import org.springframework.context.annotation.Import;
   import com.example.graphql.UserQuery;
   import graphql.GraphQL;
   import graphql.schema.GraphQLSchema;
   import graphql.schema.idl.RuntimeWiring;
   import graphql.schema.idl.SchemaGenerator;
   import graphql.schema.idl.SchemaParser;
   import graphql.schema.idl.TypeDefinitionRegistry;

   @Configuration
   @Import({UserQuery.class})
   public class GraphQLConfig {

       @Bean
       public GraphQL graphQL(UserQuery userQuery) {
           TypeDefinitionRegistry typeRegistry = new SchemaParser().parse(getClass().getResourceAsStream("/schema.graphqls"));
           RuntimeWiring runtimeWiring = buildRuntimeWiring(userQuery);
           GraphQLSchema schema = new SchemaGenerator().makeExecutableSchema(typeRegistry, runtimeWiring);
           return GraphQL.newGraphQL(schema).build();
       }

       private RuntimeWiring buildRuntimeWiring(UserQuery userQuery) {
           return RuntimeWiring.newRuntimeWiring()
                   .type("Query", builder -> builder.dataFetcher("getUser", userQuery))
                   .build();
       }
   }
