public enum Recurrence {
    DAILY("Daily", "0 0 * * * ?"),  // Example cronValue for daily recurrence
    WEEKLY("Weekly", "0 0 * * 0 ?"),  // Example cronValue for weekly recurrence
    MONTHLY("Monthly", "0 0 1 * * ?"),  // Example cronValue for monthly recurrence
    QUARTERLY("Quarterly", "0 0 1 1,4,7,10 ?"),  // Example cronValue for quarterly recurrence
    HALF_YEARLY("Half-Yearly", "0 0 1 1,7 ?"),  // Example cronValue for half-yearly recurrence
    YEARLY("Yearly", "0 0 1 1 ?");  // Example cronValue for yearly recurrence

    private final String name;
    private final String cronValue;

    Recurrence(String name, String cronValue) {
        this.name = name;
        this.cronValue = cronValue;
    }

    public String getName() {
        return name;
    }

    public String getCronValue() {
        return cronValue;
    }
}
```

