    getUser(id: ID!): Response
  }

  type User {
    id: ID!
    name: String
  }

  # Custom response type
  type Response {
    success: Boolean!
    data: User
    message: String
  }
`;

// Sample data
const users = [
  { id: "1", name: "Alice" },
  { id: "2", name: "Bob" },
];

// Resolvers
const resolvers = {
  Query: {
    getUser: (parent, args) => {
      const user = users.find((u) => u.id === args.id);
      if (!user) {
        throw new ValidationError(`User with ID ${args.id} not found`);
      }
      // Format success response here
      return {
        success: true,
        data: user,
        message: "User retrieved successfully",
      };
    },
  },
};

// Validation plugin for additional checks
const validationPlugin: ApolloServerPlugin = {
  async requestDidStart() {
    return {
      async didResolveOperation(context) {
        const { operationName, request } = context;
        if (operationName === "getUser" && !request.variables.id) {
          throw new ValidationError("User ID is required");
        }
      },
    };
  },
};

// Apollo Server instance
const server = new ApolloServer({
  typeDefs,
  resolvers,
  plugins: [validationPlugin],
  formatError: (err) => {
    if (err.extensions.code === "VALIDATION_ERROR") {
      return {
        message: err.message,
        success: false,
        statusCode: 400,
        code: err.extensions.code,
      };
    }
    return err;
  },
});

await startStandaloneServer(server, {
  listen: { port: 4000 },
}).then(({ url }) => {
  console.log(`Server ready at ${url}`);
});
```

### Explanation
- **Custom Response Type**: The `Response` type in the schema wraps the `data` (in this case, `User`), a `success` flag, and a `message`.
- **Resolver Formatting**: The `getUser` resolver formats its success response by returning an object that matches the `Response` type, containing `success`, `data`, and `message` fields.
- **Error Handling**: If an error occurs (e.g., if the user isn’t found), a `ValidationError` is thrown, and `formatError` customizes the error structure.

### 2. **Using Context or Middleware for Global Success Response Formatting**
For more centralized formatting, you could modify the context or response globally, although this would require some custom handling since Apollo doesn’t natively support `formatResponse`.

Using a pattern like this keeps your GraphQL responses consistent, regardless of whether they succeed or fail.

