    public WordMutationResolver(WordRepository wordRepository) {
        this.wordRepository = wordRepository;
    }

    public Word createWord(String name, String meaning, String example) {
        Word word = new Word();
        word.setName(name);
        word.setMeaning(meaning);
        word.setExample(example);
        return wordRepository.save(word);
    }

    public Word updateWord(String id, String name, String meaning, String example) {
        Word existingWord = wordRepository.findById(id).orElse(null);
        if (existingWord != null) {
            if (name != null) existingWord.setName(name);
            if (meaning != null) existingWord.setMeaning(meaning);
            if (example != null) existingWord.setExample(example);
            return wordRepository.save(existingWord);
        }
        return null;
    }

    public Boolean deleteWord(String id) {
        Word existingWord = wordRepository.findById(id).orElse(null);
        if (existingWord != null) {
            wordRepository.delete(existingWord);
            return true;
        }
        return false;
    }
}

// Application.java
