                .type("Query", builder -> builder.dataFetcher("allWords", this::getAllWords)
                        .dataFetcher("word", this::getWord))
                .type("Mutation", builder -> builder.dataFetcher("createWord", this::createWord)
                        .dataFetcher("updateWord", this::updateWord)
                        .dataFetcher("deleteWord", this::deleteWord))
                .build();
    }

