    useNewUrlParser: true,
    useUnifiedTopology: true
})
.then(() => {
    console.log('Connected to MongoDB');
    // Read vocab.json file
    fs.readFile('vocab.json', 'utf8', (err, data) => {
        if (err) {
            console.error('Error reading vocab.json:', err);
            return;
        }
        const vocabData = JSON.parse(data);
        // Process each word in vocabData
        vocabData.forEach(wordData => {
            // Create or update document in MongoDB
            Word.findOneAndUpdate(
                { word: wordData.word },
                { $set: { meanings: wordData.meanings, examples: wordData.examples } },
                { upsert: true, new: true },
                (err, doc) => {
                    if (err) {
                        console.error('Error creating/updating document:', err);
                    } else {
                        console.log('Document created/updated:', doc);
                    }
                }
            );
        });
    });
})
.catch(err => {
    console.error('Error connecting to MongoDB:', err);
});
