    // Create a new Word document
    const newWord = new Word({
      word,
      meaning,
    });

    // Save the word document to the database
    await newWord.save();

    // Send a success response
    res.status(201).json({ message: 'Word saved successfully!' });
  } catch (error) {
    // Handle errors
    res.status(500).json({ error: error.message });
  }
});

// Start the server
