const express = require('express');
const fs = require('fs');
const path = require('path');
const marked = require('marked');

const app = express();

app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

const publicFolderPath = path.join(__dirname, '../public');

// Function to read files recursively
const readFilesRecursively = (dir, basePath = '') => {
    let files = fs.readdirSync(dir, { withFileTypes: true });
    let fileTree = [];
    files.forEach(file => {
        const filePath = path.join(basePath, file.name);
        if (file.isDirectory()) {
            fileTree.push({
                name: file.name,
                type: 'directory',
                children: readFilesRecursively(path.join(dir, file.name), filePath)
            });
        } else if (path.extname(file.name) === '.md') {
            fileTree.push({
                name: file.name,
                type: 'file',
                path: filePath
            });
        }
    });
    return fileTree;
};

// Route to render the file list and optionally render selected MD file as HTML
app.get('/', (req, res) => {
    const fileList = readFilesRecursively(publicFolderPath, publicFolderPath);
    let htmlContent = null;

    // Check if a specific MD file is requested
    if (req.query.filename) {
        const filename = req.query.filename;
        const filePath = path.join(publicFolderPath, filename);
        try {
            const data = fs.readFileSync(filePath, 'utf8');
            htmlContent = marked(data);
        } catch (err) {
            console.error('Error reading file:', err);
        }
    }

    res.render('index', { fileList, htmlContent });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
```

