Here’s a centralized approach to handle HTTP calls in a React.js application using Axios and error handling:

### 1. Install Axios
First, install Axios if you haven't already:

```bash
npm install axios
```

### 2. Create a Service File for HTTP Calls

Create a new file, `httpService.js`, in a `services` directory (or any other appropriate directory):

```javascript
import axios from 'axios';

const apiClient = axios.create({
  baseURL: process.env.REACT_APP_API_BASE_URL || 'http://localhost:3000/api',
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000, // Optional: set a timeout for requests
});

// Request interceptor
apiClient.interceptors.request.use(
  (config) => {
    // Add authorization token if needed
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    // Centralized error handling
    if (error.response) {
      // Server responded with a status other than 2xx
      console.error('Error response:', error.response);
    } else if (error.request) {
      // Request was made but no response was received
      console.error('Error request:', error.request);
    } else {
      // Something else happened while setting up the request
      console.error('Error message:', error.message);
    }
    return Promise.reject(error);
  }
);

const httpService = {
  get: (url, config = {}) => apiClient.get(url, config),
  post: (url, data, config = {}) => apiClient.post(url, data, config),
  put: (url, data, config = {}) => apiClient.put(url, data, config),
  delete: (url, config = {}) => apiClient.delete(url, config),
};

export default httpService;
```

### 3. Use the Service in Your Components

