Yes, you can introduce methods in your custom hooks to interact with the REST endpoints for CRUD operations. Here's an updated version of your `useSharedConfigurations` hook with methods for creating, reading, updating, and deleting `RelatedNode` documents:

```javascript
import React, {
  createContext,
  useContext,
  useState,
} from "react";
import axios from "axios";

const defaultStyles = {
  greenBorder: { border: "1px solid green" },
};

// Initial shared data
const initialSharedData = {
  selectedNode: null,
  showDetails: false,
  showPreviousRelations: false,
  showNextRelations: false,
  styles: defaultStyles,
};

// Create a context for shared configurations and data
const SharedConfigurationsContext = createContext();

// Create a provider component
const SharedConfigurationsProvider = ({ children }) => {
  const [sharedData, setSharedData] = useState(initialSharedData);

  const setSelectedNode = (selectedNode) => {
    if (selectedNode) {
      setSharedData((prev) => ({ ...prev, selectedNode: selectedNode }));
    }
  };

  const createNode = async (nodeData) => {
    try {
      const response = await axios.post("http://localhost:3002/node-story", nodeData);
      return response.data;
    } catch (error) {
      console.error("Error creating node:", error);
      throw error;
    }
  };

  const getNode = async (nodeId) => {
    try {
      const response = await axios.get(`http://localhost:3002/node-story/${nodeId}`);
      return response.data;
    } catch (error) {
      console.error("Error fetching node:", error);
      throw error;
    }
  };

  const updateNode = async (nodeId, updatedData) => {
    try {
      const response = await axios.put(`http://localhost:3002/node-story/${nodeId}`, updatedData);
      return response.data;
    } catch (error) {
      console.error("Error updating node:", error);
      throw error;
    }
  };

  const deleteNode = async (nodeId) => {
    try {
      await axios.delete(`http://localhost:3002/node-story/${nodeId}`);
    } catch (error) {
      console.error("Error deleting node:", error);
      throw error;
    }
  };

  const SharedService = {
    setSelectedNode,
    createNode,
    getNode,
    updateNode,
    deleteNode,
  };

  return (
    <SharedConfigurationsContext.Provider
      value={{
        sharedData,
        SharedService,
      }}
    >
      {children}
    </SharedConfigurationsContext.Provider>
  );
};

// Custom hook to use shared configurations and data
const useSharedConfigurations = () => useContext(SharedConfigurationsContext);

export { SharedConfigurationsProvider, useSharedConfigurations };
```

