import React, { useEffect, useState } from "react";
import { Navigate, Route, Routes, useNavigate } from "react-router-dom";
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { clearToken, getToken } from "./common/authService";
import HorizontalMenu from "./HorizontalMenu";
import PublicRoutes from "./routes/PublicRoutes";
import AuthenticatedRoutes from "./routes/AuthenticatedRoutes";
import NotFound from "./components/NotFound";

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const history = useNavigate();

  useEffect(() => {
    const token = getToken(); // Replace with your token retrieval logic
    if (token) {
      setIsAuthenticated(true);
    } else {
      if (window.location.pathname !== "/register") {
        history("/login");
      }
    }
  }, [history]);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    clearToken();
    setIsAuthenticated(false);
    history("/login");
  };

  return (
    <>
      <ToastContainer
        position="top-center"
        autoClose={5000}
        hideProgressBar
        newestOnTop={false}
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable={false}
        pauseOnHover
        theme="light"
      />
      {isAuthenticated && (
        <HorizontalMenu
          isAuthenticated={isAuthenticated}
          handleLogout={handleLogout}
        />
      )}
      <Routes>
        <Route path="/" element={<Navigate to="/login" />} />
        <Route path="/login" element={<PublicRoutes onLogin={handleLogin} />} />
        <Route path="/register" element={<PublicRoutes />} />
        {isAuthenticated && <AuthenticatedRoutes />}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </>
  );
}

export default App;
```

