const TextDiffViewer = ({ oldContent, newContent }) => {
    const diff = Diff.diffWords(oldContent, newContent);

    return (
        <div style={styles.diffContainer}>
            {diff.map((part, index) => {
                const style = part.added
                    ? styles.added
                    : part.removed
                    ? styles.removed
                    : styles.normal;

                return (
                    <span key={index} style={style}>
                        {part.value}
                    </span>
                );
            })}
        </div>
    );
};

