const NODE_ITEM_TYPES = [
  "category",
  "question",
  "topic",
  "section",
  "link",
  "tech-stack",
  "memory-map",
  "conversation",
  "message"
];

const deleteObjectById = (arr, uniqueId, idFieldName = "uniqueId") => {
  return arr.filter((obj) => obj[idFieldName] !== uniqueId);
};

const updateOrAdd = (arr, newObj, idFieldName = "uniqueId") => {
  const index = arr.findIndex(
    (obj) => obj[idFieldName] === newObj[idFieldName]
  );

  if (index !== -1) {
    arr[index] = newObj;
  } else {
    arr.push(newObj);
  }

  return arr;
};

const CONSTANTS = {
  DRAFT_RELATION_ID_PREFIX: 'DRAFT_RELATION_ID_',
}

const NodeItemForm = ({
  initialFormData = {},
  onSave = () => { },
  onCancelEdit = () => { },
}) => {
  const {
    SharedService: {
      refreshNodes,
      createNode,
      getNodeByUniqueId,
      updateNodeByUniqueId,
    },
    sharedData: { selectedNode },
  } = useSharedConfigurations();

  const [formErrors, setFormErrors] = useState([]);
  const [showRelationForm, setShowRelationForm] = useState(false);
  const [selectedRelation, setSelectedRelation] = useState(null);
  const [formData, setFormData] = useState({
    uniqueId: initialFormData?.uniqueId || "",
    name: initialFormData?.name || "",
    relations: initialFormData?.relations || [],
    itemType: initialFormData?.itemType || "",
  });

  useEffect(() => {
    if (formData.uniqueId) {
      getNodeByUniqueId(formData.uniqueId).then(() => {
        setFormData({ ...selectedNode });
      });
    }
  }, [formData.uniqueId, getNodeByUniqueId, selectedNode]);

  const validateForm = () => {
    const errors = [];
    if (!formData.name.trim()) errors.push("Name is required");
    if (!formData.itemType.trim()) errors.push("Node Item Type is required");
    setFormErrors(errors);
    return errors.length === 0;
  };

  const handleSubmitMemoryMap = (event) => {
    event.preventDefault();
    if (!validateForm()) return;

    const updatedNodeItemObj = {
      ...formData,
      relations: [...formData.details?.map(det => ({
        ...det,
        uniqueId: det.uniqueId && !det.uniqueId.startsWith(CONSTANTS.DRAFT_RELATION_ID_PREFIX) ? det.uniqueId : ''
      }))],
    };

    if (formData.uniqueId) {
      updateNodeByUniqueId(formData.uniqueId, updatedNodeItemObj).then(() => {
        setFormData(() => ({ ...selectedNode }));
      });
    } else {
      createNode(updatedNodeItemObj).then(() => {
        refreshNodes();
        onSave();
      });
