          onChange={handleInputChange}
          style={{ width: "90%" }}
        />
      </div>

      <div style={{ display: "block", padding: "10px" }}>
        <div>
          <label
            style={{ width: "9%", fontWeight: "bold" }}
            htmlFor="description"
          >
            Relations:
          </label>
          <CustomButton
            onClick={() => {
              setSelectedRelation(null);
              setShowRelationForm(true);
            }}
          >
            Add
