    const textToCopy = "This is the text to copy";

    return (
        <div>
            <span>{textToCopy}</span>
            <CopyToClipboard text={textToCopy} onCopy={() => setCopied(true)}>
                <button>Copy to Clipboard</button>
            </CopyToClipboard>
            {copied ? <span style={{ color: 'green' }}>Copied!</span> : null}
        </div>
    );
};

export default CopyTextComponent;
```

### Usage

To use this component, simply import it and include it in your JSX:

```javascript
import React from 'react';
import CopyTextComponent from './CopyTextComponent';

const App = () => (
    <div>
        <h1>Copy to Clipboard Example</h1>
        <CopyTextComponent />
    </div>
);

export default App;
```

