export const applyStyles = (element, styles) => {
    for (const property in styles) {
        element.style[property] = styles[property];
    }
};

export const resetStyles = (element) => {
    element.style.cssText = '';
};

const createElement = (
    tag,
    attributes = {},
    innerHTML = "",
    styles = {},
    events = {}
) => {
    const element = document.createElement(tag);
    Object.keys(attributes).forEach((attr) =>
        element.setAttribute(attr, attributes[attr])
    );
    applyStyles(element, styles);
    element.innerHTML = innerHTML;

    // Attach event listeners
    Object.keys(events).forEach((event) => {
        element.addEventListener(event, events[event]);
    });

    return element;
};

export const createButton = (attributes = {}, innerHTML = '', styles = {}, events = {}) => {
    return createElement('button', attributes, innerHTML, styles, events);
};

export const createDiv = (attributes = {}, innerHTML = '', styles = {}, events = {}) => {
    return createElement('div', attributes, innerHTML, styles, events);
};

export const createInput = (attributes = {}, innerHTML = '', styles = {}, events = {}) => {
    return createElement('input', attributes, innerHTML, styles, events);
};

export const createSelect = (attributes = {}, options = [], styles = {}, events = {}) => {
    const select = createElement('select', attributes, '', styles, events);
    options.forEach(optionData => {
        const option = document.createElement('option');
        option.value = optionData.value;
        option.innerText = optionData.label;
        select.appendChild(option);
    });
    return select;
};
```

### Explanation

1. **Container Setup**: A container `div` wraps the `input` and the dropdown list `div`.
2. **Input Element**: Used to show the selected option and trigger the dropdown visibility on click.
3. **Dropdown List**: Contains `div` elements styled as options. It is initially hidden and shown/hidden on input click.
4. **Event Handling**: Clicking the input toggles the visibility of the dropdown list. Selecting an option updates the input value and hides the dropdown. Hovering over options changes their background color.

This implementation allows you to create a custom dropdown using basic HTML, CSS, and JavaScript, offering more control over the appearance and behavior compared to the default `select` element.

