            border-radius: 3px;
        }
    </style>
</head>
<body>
    <div class="tooltip" data-tooltip="This is a <strong>styled</strong> tooltip!">Hover over this div</div>
    <span class="tooltip" data-tooltip="Another <em>styled</em> tooltip!">Hover over this span</span>
    <button class="tooltip" data-tooltip="Button <u>tooltip</u> example!">Hover over this button</button>
    <input type="text" class="tooltip" data-tooltip="Input tooltip with <code>code</code>!" value="Hover over this input">
    <a href="#" class="tooltip" data-tooltip="Link tooltip with <a href='#'>link</a> inside!">Hover over this link</a>

    <div id="tooltip"></div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const tooltipElements = document.querySelectorAll('.tooltip');
            const tooltip = document.getElementById('tooltip');

            tooltipElements.forEach(element => {
                element.addEventListener('mouseenter', event => {
                    const tooltipText = event.target.getAttribute('data-tooltip');
                    tooltip.innerHTML = tooltipText;
                    tooltip.style.display = 'block';
                    const rect = event.target.getBoundingClientRect();
                    tooltip.style.left = `${rect.left + window.scrollX + event.target.offsetWidth / 2}px`;
                    tooltip.style.top = `${rect.top + window.scrollY - tooltip.offsetHeight - 10}px`;
                });

                element.addEventListener('mouseleave', () => {
                    tooltip.style.display = 'none';
                });
            });

            document.addEventListener('mousemove', event => {
                if (tooltip.style.display === 'block') {
                    const rect = tooltip.getBoundingClientRect();
                    tooltip.style.left = `${event.clientX - rect.width / 2}px`;
                    tooltip.style.top = `${event.clientY - rect.height - 10}px`;
                }
            });
        });
    </script>
</body>
</html>
```

### Explanation:
1. **HTML Structure**: Contains various elements with the class `tooltip` and the `data-tooltip` attribute which holds the HTML content for the tooltip.
2. **CSS**: Inline CSS to style the tooltip and the elements.
3. **JavaScript**:
   - **DOMContentLoaded** event to ensure the DOM is fully loaded before executing the script.
   - **Mouse Enter Event**: Shows the tooltip with the specified HTML content and positions it relative to the hovered element.
   - **Mouse Leave Event**: Hides the tooltip.
   - **Mouse Move Event**: Ensures the tooltip follows the mouse cursor and stays positioned correctly.

This script combines everything into a single HTML file and ensures the custom tooltip functionality is applied to all elements with the `tooltip` class and `data-tooltip` attribute.

