const addNewButton = () => {
    elementAdderUtility.addElementWithPromise({
        elementType: 'button',
        parentElementId: 'myContainer',
        style: {
            backgroundColor: 'blue',
            color: 'white'
        },
        innerText: 'Click Me',
        onClick: () => alert('Button Clicked')
    }).then(button => {
        console.log('Button added:', button);
    }).catch(error => {
        console.error('Error adding button:', error);
    });
};

// Assuming there is a div with id 'myContainer' in the HTML
