    return state.isMouseHover ? { ...styles.button, ...styles.buttonHover } : styles.button;
};

// Event handlers
const handleButtonClick = () => {
    count++;
    buttonAddEl.innerHTML = `Current count {${count}}`;
};

const handleMouseOver = () => {
    state.isMouseHover = true;
    updateButtonStyle();
};

const handleMouseOut = () => {
    state.isMouseHover = false;
    updateButtonStyle();
};

// Update button style based on current state
const updateButtonStyle = () => {
    resetStyles(buttonAddEl);
    applyStyles(buttonAddEl, getButtonStyle(state));
};

// Create initial elements
const myContainerDiv = createDiv({}, "", {}, {});
const myButtonContainerDiv = createDiv({}, "", {}, {});
const myElementsContainerDiv = createDiv({}, "", {}, {});

const buttonAddEl = createButton(
    {},
    `Current count {${count}}`,
    styles.button,
    {
        click: handleButtonClick,
        mouseover: handleMouseOver,
        mouseout: handleMouseOut,
    }
);

// Append elements to the DOM
myButtonContainerDiv.appendChild(buttonAddEl);
myContainerDiv.appendChild(myButtonContainerDiv);
myContainerDiv.appendChild(myElementsContainerDiv);
document.body.appendChild(myContainerDiv);

// Add initial content to elements container
const addInitialContent = () => {
    const initialContent = createDiv({}, "Initial content", {}, {});
    myElementsContainerDiv.appendChild(initialContent);
};

addInitialContent();
```

### Explanation of Refactor:

1. **Styles**: Styles are defined in a single object, `styles`, and `getButtonStyle` function dynamically determines which styles to apply based on the `state`.

2. **State Management**: A `state` object is used to keep track of whether the mouse is hovering over the button.

3. **Event Handlers**: Event handlers (`handleButtonClick`, `handleMouseOver`, and `handleMouseOut`) are defined separately for better readability and reusability.

4. **Style Updates**: `updateButtonStyle` function resets and re-applies the button styles based on the current state.

5. **Element Creation and Appending**: Elements are created using helper functions and appended to the DOM in a clear and organized manner.

This structure provides a clear separation of concerns, making the code easier to understand, maintain, and extend.

