import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import com.graphql.spring.boot.annotations.GraphQLController;
import com.graphql.spring.boot.annotations.QueryMapping;
import com.graphql.spring.boot.annotations.MutationMapping;

@Controller
@GraphQLController
public class GraphQLController {

    @QueryMapping
    public Integer add(int a, int b) {
        return a + b;
    }

    @QueryMapping
    public String greet(String name) {
        return "Hello " + name;
    }

    @MutationMapping
    public Integer multiply(int a, int b) {
        return a * b;
    }
}
```

In this code:

- `@QueryMapping` is used to define GraphQL query endpoints. The method name is the field name in the GraphQL schema.
- `@MutationMapping` is used to define GraphQL mutation endpoints. Again, the method name will be the field name in the GraphQL schema.
- The controller class is annotated with `@GraphQLController` to indicate that it provides GraphQL endpoints.

